#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<string> grid(h);
    for (int i = 0; i < h; i++) {
        cin >> grid[i];
    }

    vector<vector<char>> safe(h, vector<char>(w, 0));
    vector<pair<int, int>> stack;
    for (int x = 0; x < h; x++) {
        for (int y = 0; y < w; y++) {
            if ((x == 0 || x == h - 1 || y == 0 || y == w - 1) && grid[x][y] == 'O') {
                safe[x][y] = 1;
                stack.push_back({x, y});
            }
        }
    }
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    while (!stack.empty()) {
        pair<int, int> cell = stack.back();
        stack.pop_back();
        for (int d = 0; d < 4; d++) {
            int a = cell.first + dx[d], b = cell.second + dy[d];
            if (a >= 0 && a < h && b >= 0 && b < w && grid[a][b] == 'O' && !safe[a][b]) {
                safe[a][b] = 1;
                stack.push_back({a, b});
            }
        }
    }
    for (int x = 0; x < h; x++) {
        for (int y = 0; y < w; y++) cout << (safe[x][y] ? 'O' : 'X');
        cout << "\n";
    }

    return 0;
}

